"""Real Inbox controls with controlled records; blocks every external request/write."""
import unittest
from pathlib import Path
from urllib.parse import urlparse
from playwright.async_api import async_playwright,expect
HTML='''<!doctype html><html><head><meta name="viewport" content="width=device-width, initial-scale=1"><script>window.__oj_refresh_installed__=true;window.$RefreshReg$=()=>{};window.$RefreshSig$=()=>type=>type;</script></head><body><div id="root"></div><script type="module" src="/scripts/browser/financial-inbox.fixture.tsx"></script></body></html>'''
class InboxTests(unittest.IsolatedAsyncioTestCase):
 async def asyncSetUp(self):
  self.p=await async_playwright().start();self.browser=await self.p.chromium.launch(headless=True);self.context=await self.browser.new_context(viewport={'width':1280,'height':1800});self.page=await self.context.new_page();self.errors=[];self.blocked=[];self.page.on('pageerror',lambda e:self.errors.append(str(e)))
  async def isolate(route):
   r=route.request;u=urlparse(r.url)
   if u.netloc!='localhost:8080' or r.method not in ('GET','HEAD'):self.blocked.append(u.hostname);await route.abort()
   elif u.path in ['/inbox','/transfers']:await route.fulfill(content_type='text/html',body=HTML)
   elif u.path in ['/src/lib/store.tsx','/src/lib/import-repository.ts','/src/lib/offline.ts','/src/integrations/supabase/client.ts']:
    exports={'/src/lib/store.tsx':'useStore','/src/lib/import-repository.ts':'listImportRules,listImports,statementEvidence,listImportRows,reviseRows','/src/lib/offline.ts':'readReviewContext,writeReviewContext,localDrafts,localToFile,putLocalDraft,removeLocalDraft,fileToLocal','/src/integrations/supabase/client.ts':'supabase'}[u.path];await route.fulfill(content_type='application/javascript',body=f'export {{ {exports} }} from "/scripts/browser/financial-inbox-mocks.tsx";')
   else:await route.continue_()
  await self.context.route('**/*',isolate);await self.page.goto('http://localhost:8080/inbox?section=review');await expect(self.page.get_by_role('heading',name='91 transactions needing attention')).to_be_visible()
 async def asyncTearDown(self):
  Path('/tmp/browser/v512').mkdir(parents=True,exist_ok=True);self.assertEqual(await self.page.evaluate('Math.max(0,document.documentElement.scrollWidth-innerWidth)'),0);await self.page.screenshot(path=f'/tmp/browser/v512/{self._testMethodName}.png');self.assertEqual(self.errors,[]);self.assertEqual(self.blocked,[]);await self.browser.close();await self.p.stop()
 async def choose(self,name):
  await self.page.get_by_role('button',name='Select',exact=True).click();await self.page.get_by_role('menuitem',name=name,exact=True).click()
 async def test_matching_scope_and_filter_changes(self):
  await self.choose('Select all visible (40)');await expect(self.page.get_by_role('region',name='Selected transaction summary').get_by_text('40 transactions selected',exact=True)).to_be_visible()
  await self.page.get_by_label('Search financial review').fill('Controlled 90');await expect(self.page.get_by_text('Selection scope: 0 matching the current filters · 40 outside the current filters')).to_be_visible();await self.choose('Select all matching (1)');await expect(self.page.get_by_text('Selection scope: 1 matching the current filters · 0 outside the current filters')).to_be_visible()
 async def test_selected_summary_stays_visible_while_scrolling(self):
  await self.choose('Select all matching (91)')
  for width,height in [(1280,1800),(1180,820),(402,725)]:
   await self.page.set_viewport_size({'width':width,'height':height})
   summary=self.page.get_by_role('region',name='Selected transaction summary')
   await self.page.evaluate('window.scrollTo(0, document.documentElement.scrollHeight / 2)')
   await self.page.wait_for_timeout(150)
   box=await summary.bounding_box()
   self.assertIsNotNone(box)
   self.assertGreaterEqual(box['y'],0)
   self.assertLessEqual(box['y']+box['height'],height)
   await summary.screenshot(path=f'/tmp/browser/v512/{width}-sticky-summary.png')
   self.assertEqual(await self.page.evaluate('inboxFixture.saves.length'),0)
   await self.page.evaluate('window.scrollTo(0,0)')
 async def test_preview_save_reload_and_undo(self):
  await self.choose('Select all matching (91)');await self.page.get_by_role('button',name='Categorise',exact=True).click();await self.page.get_by_label('Bulk review category').click();await self.page.get_by_role('option',name='Groceries',exact=True).click();await self.page.get_by_role('button',name='Review & Apply',exact=True).click();self.assertEqual(await self.page.evaluate('inboxFixture.saves.length'),0)
  await self.page.evaluate('inboxFixture.failNextSave=true');await self.page.get_by_role('button',name='Confirm & Apply Changes').click();await expect(self.page.get_by_role('button',name='Unable to Save — Retry')).to_be_visible();await self.page.get_by_role('button',name='Unable to Save — Retry').click();await expect(self.page.get_by_role('heading',name='0 transactions needing attention')).to_be_visible();self.assertEqual(await self.page.evaluate('inboxFixture.saves[0].length'),91)
  await self.page.get_by_role('button',name='Undo correction').click();await expect(self.page.get_by_role('heading',name='91 transactions needing attention')).to_be_visible();self.assertEqual(await self.page.evaluate('inboxFixture.transactions.reduce((s,e)=>s+e.amount,0)'),4186)
  await self.page.reload();await expect(self.page.get_by_role('heading',name='91 transactions needing attention')).to_be_visible()
 async def test_four_layouts_and_navigation(self):
  for name,w,h in [('iphone',402,874),('ipad-portrait',820,1180),('ipad-landscape',1180,820),('desktop',1280,1800)]:
   await self.page.set_viewport_size({'width':w,'height':h});await self.page.screenshot(path=f'/tmp/browser/v512/{name}.png');self.assertEqual(await self.page.evaluate('Math.max(0,document.documentElement.scrollWidth-innerWidth)'),0)
  await self.page.get_by_role('link',name='Review History',exact=True).first.click();await expect(self.page.get_by_role('heading',name='Review History',exact=True)).to_be_visible();await self.page.get_by_role('link',name='Review',exact=True).click();await expect(self.page.get_by_role('heading',name='91 transactions needing attention')).to_be_visible()
 async def test_mobile_approval_cancel_failure_and_confirm(self):
  await self.page.set_viewport_size({'width':402,'height':725});await self.page.goto('http://localhost:8080/inbox?section=review&fixture=approvals');await expect(self.page.get_by_role('heading',name='2 transactions needing attention')).to_be_visible()
  await self.choose('Select all matching (2)');await self.page.get_by_role('button',name='Confirm as reviewed (1)').click();await self.page.get_by_role('dialog').get_by_role('button',name='Cancel',exact=True).click();self.assertIsNone(await self.page.evaluate('inboxFixture.transactions[0].reconciledAt'))
  await self.page.get_by_role('button',name='Confirm as reviewed (1)').click();await self.page.evaluate('inboxFixture.failNextSave=true');await self.page.get_by_role('dialog').screenshot(path='/tmp/browser/v512/phone-review-confirmation.png');await self.page.get_by_role('dialog').get_by_role('button',name='Confirm',exact=True).click();await expect(self.page.get_by_text('Could not confirm: Controlled confirmation interrupted')).to_be_visible();self.assertIsNone(await self.page.evaluate('inboxFixture.transactions[0].reconciledAt'))
  await self.page.get_by_role('dialog').screenshot(path='/tmp/browser/v512/phone-review-confirmation.png');await self.page.get_by_role('dialog').get_by_role('button',name='Confirm',exact=True).click();await expect(self.page.get_by_role('heading',name='1 transactions needing attention')).to_be_visible();await self.page.reload();await expect(self.page.get_by_role('heading',name='1 transactions needing attention')).to_be_visible();self.assertEqual(await self.page.evaluate('inboxFixture.transactions.length'),2)
 async def test_mobile_history_confirmed_undo(self):
  await self.page.set_viewport_size({'width':402,'height':725});await self.choose('Select all matching (91)');await self.page.get_by_role('button',name='Categorise',exact=True).click();await self.page.get_by_label('Bulk review category').click();await self.page.get_by_role('option',name='Groceries',exact=True).click();await self.page.get_by_role('button',name='Review & Apply',exact=True).click();await self.page.get_by_role('dialog').screenshot(path='/tmp/browser/v512/phone-category-confirmation.png');await self.page.get_by_role('button',name='Confirm & Apply Changes').click();await expect(self.page.get_by_role('heading',name='0 transactions needing attention')).to_be_visible()
  await self.page.get_by_role('link',name='Review History',exact=True).first.click();await self.page.get_by_role('button',name='Review undo').click();await self.page.get_by_role('dialog').get_by_role('button',name='Cancel').click();self.assertEqual(await self.page.evaluate('inboxFixture.transactions[0].category'),'Groceries');await self.page.get_by_role('button',name='Review undo').click();await self.page.get_by_role('button',name='Confirm undo').click();await expect(self.page.get_by_text('Restored',exact=False).first).to_be_visible();await self.page.get_by_role('link',name='Review',exact=True).click();await expect(self.page.get_by_role('heading',name='91 transactions needing attention')).to_be_visible()
 async def test_mobile_transfer_approval_retry_reload_and_undo(self):
  await self.page.set_viewport_size({'width':402,'height':725});await self.page.goto('http://localhost:8080/transfers?fixture=transfers');await expect(self.page.get_by_role('button',name='Review',exact=True)).to_be_visible();before=await self.page.evaluate('inboxFinancials()');await self.page.get_by_role('button',name='Review',exact=True).click();self.assertEqual(await self.page.evaluate('inboxFixture.links.length'),0);await self.page.get_by_role('dialog').screenshot(path='/tmp/browser/v512/phone-transfer-confirmation.png');await self.page.get_by_role('dialog').get_by_role('button',name='Cancel').click();await self.page.get_by_role('button',name='Review',exact=True).click();await self.page.evaluate('inboxFixture.failNextSave=true');await self.page.get_by_role('button',name='Confirm transfer',exact=True).click();await expect(self.page.get_by_role('alert').filter(has_text='Controlled transfer interrupted')).to_be_visible();await self.page.get_by_role('button',name='Confirm transfer',exact=True).click();await expect(self.page.get_by_role('button',name='Unlink',exact=True)).to_be_visible();after=await self.page.evaluate('inboxFinancials()');self.assertEqual(before['count'],after['count']);self.assertEqual(before['balances'],after['balances']);self.assertEqual(after['flow'],{'income':0,'spent':0,'net':0})
  await self.page.get_by_role('button',name='Unlink',exact=True).click();await self.page.evaluate('inboxFixture.failNextSave=true');await self.page.get_by_role('button',name='Confirm undo',exact=True).click();await expect(self.page.get_by_text('Later edit blocks restoration',exact=True)).to_be_visible();self.assertEqual(await self.page.evaluate('inboxFixture.transactions[1].transferCounterpartOf'),'debit');await self.page.get_by_role('button',name='Confirm undo',exact=True).click();await expect(self.page.get_by_role('button',name='Review',exact=True)).to_be_visible();self.assertEqual(before,await self.page.evaluate('inboxFinancials()'));await self.page.reload();await expect(self.page.get_by_role('button',name='Review',exact=True)).to_be_visible()
 async def test_ipad_account_correction_approval_and_history_undo(self):
  await self.page.set_viewport_size({'width':820,'height':1180});await self.page.get_by_label('Search financial review').fill('Controlled 0');await self.choose('Select all matching (1)');await self.page.get_by_role('button',name='Account & financial type',exact=True).click();await self.page.get_by_label('Payment account').click();await self.page.get_by_role('option',name='Destination bank 9876',exact=True).click();await self.page.get_by_role('button',name='Preview account & type changes').click();await expect(self.page.get_by_role('heading',name='Confirm financial correction')).to_be_visible();self.assertEqual(await self.page.evaluate('inboxFixture.transactions[0].accountId'),'bank');await self.page.get_by_role('button',name='Confirm financial changes').click();await expect(self.page.get_by_role('heading',name='Confirm financial correction')).not_to_be_visible();self.assertEqual(await self.page.evaluate('inboxFixture.transactions[0].accountId'),'destination');await self.page.get_by_role('link',name='Review History',exact=True).first.click();await self.page.get_by_role('button',name='Review undo').click();await self.page.get_by_role('button',name='Confirm undo').click();self.assertEqual(await self.page.evaluate('inboxFixture.transactions[0].accountId'),'bank');self.assertEqual(await self.page.evaluate('inboxFixture.transactions.length'),91)
 async def test_phone_organisation_without_trip_approval_and_undo(self):
  await self.page.set_viewport_size({'width':402,'height':725});await self.page.get_by_label('Search financial review').fill('Controlled 0');await self.choose('Select all matching (1)');await self.page.get_by_role('button',name='Organisation & activity',exact=True).click();await self.page.get_by_label('Mapping action').click();await self.page.get_by_role('option',name='Assign organisation (trip optional)',exact=True).click();await self.page.get_by_label('Mapping value').click();await self.page.get_by_role('option',name='Controlled employer',exact=True).click();await self.page.get_by_role('button',name='Preview mapping',exact=True).click();await expect(self.page.get_by_role('heading',name='Confirm organisation',exact=True)).to_be_visible();self.assertIsNone(await self.page.evaluate('inboxFixture.transactions[0].department??null'));await self.page.get_by_role('button',name='Confirm & Apply Organisation').click();self.assertEqual(await self.page.evaluate('inboxFixture.transactions[0].department'),'Controlled employer');self.assertIsNone(await self.page.evaluate('inboxFixture.transactions[0].tripId??null'));await self.page.get_by_role('link',name='Review History',exact=True).first.click();await self.page.get_by_role('button',name='Review undo').click();await self.page.get_by_role('button',name='Confirm undo').click();self.assertIsNone(await self.page.evaluate('inboxFixture.transactions[0].department??null'));self.assertEqual(await self.page.evaluate('inboxFixture.transactions[0].accountId'),'bank')
